INSERT INTO `npc_text` (`ID`,`text0_0`,`text0_1`,`lang0`,`prob0`,`em0_0`,`em0_1`) VALUES
(900620,'Hey! Listen! You want to learn how everything works? I know LOTS of things!$B$BPick something and I''ll explain it. You can always come back and ask again.','Hey! Listen! You want to learn how everything works? I know LOTS of things!$B$BPick something and I''ll explain it. You can always come back and ask again.',0,1,0,1),
(900621,'Your keys, $N! The number pad''s 1-9 do the same thing.$B$B1 - Sword. Tap to swing (three swings make a combo). Hold, then let go, for your stance''s charge attack.$B2 - Bow, gun or crossbow. Hold to charge a Charged Shot.$B3 - Shield. Hold to raise it. Without a shield you hold your weapon up to parry.$B4 - Boomerang.$B5 - Roll forward. Shift+Q and Shift+E roll to the sides, Shift+S is a backflip.$B6 - Potion slot. Right-click a healing or mana potion to put it there.$B7 - Mount slot. Right-click a mount to put it there.$B8 - Your character and all your bags.$B9 - The Subscreen: spellbook, talents, quest log and menu. Left and Right turn the page.$B$BTap Shift to lock on to an enemy, and tap it again to let go. Q and E change your stance. M opens the map.','Your keys, $N! The number pad''s 1-9 do the same thing.$B$B1 - Sword. Tap to swing (three swings make a combo). Hold, then let go, for your stance''s charge attack.$B2 - Bow, gun or crossbow. Hold to charge a Charged Shot.$B3 - Shield. Hold to raise it. Without a shield you hold your weapon up to parry.$B4 - Boomerang.$B5 - Roll forward. Shift+Q and Shift+E roll to the sides, Shift+S is a backflip.$B6 - Potion slot. Right-click a healing or mana potion to put it there.$B7 - Mount slot. Right-click a mount to put it there.$B8 - Your character and all your bags.$B9 - The Subscreen: spellbook, talents, quest log and menu. Left and Right turn the page.$B$BTap Shift to lock on to an enemy, and tap it again to let go. Q and E change your stance. M opens the map.',0,1,0,1),
(900622,'Fighting! My favorite part. Well, watching it.$B$BSwing with 1. Your third swing in a row is a special strike. Hold 1 and let go when the bar turns green for a charge attack - the Spin Attack costs 50 rage.$B$BRage comes from hitting and being hit. You need it for your charge attacks.$B$BStrong enemies - elites, rares and bosses - wind up a Heavy Blow or a Charged Bolt. Watch the orange bar over their health that says BLOCK! Raise your shield (3) to block it, and a blocked Heavy Blow leaves them staggered. Parry it and you only take half. Or roll away!$B$BRolling (5) dodges EVERYTHING while you''re in the air, but only from the ground.$B$BThe boomerang (4) stops whatever an enemy is casting, any enemy, and stuns or disarms it. It flies 30 yards and is ready 3 seconds after it hits.$B$BA Charged Shot (hold 2) does double damage and always crits. You stand still while you draw.','Fighting! My favorite part. Well, watching it.$B$BSwing with 1. Your third swing in a row is a special strike. Hold 1 and let go when the bar turns green for a charge attack - the Spin Attack costs 50 rage.$B$BRage comes from hitting and being hit. You need it for your charge attacks.$B$BStrong enemies - elites, rares and bosses - wind up a Heavy Blow or a Charged Bolt. Watch the orange bar over their health that says BLOCK! Raise your shield (3) to block it, and a blocked Heavy Blow leaves them staggered. Parry it and you only take half. Or roll away!$B$BRolling (5) dodges EVERYTHING while you''re in the air, but only from the ground.$B$BThe boomerang (4) stops whatever an enemy is casting, any enemy, and stuns or disarms it. It flies 30 yards and is ready 3 seconds after it hits.$B$BA Charged Shot (hold 2) does double damage and always crits. You stand still while you draw.',0,1,0,1),
(900623,'Warriors fight in three stances. Q and E switch between them.$B$BBattle Stance - any weapon. Your charge attack is the Spin Attack, which hits everyone around you. With two weapons it hits twice as many times.$B$BDefensive Stance - a one-handed weapon and a shield (taking the stance picks them from your bags). Your charge attack is Shield Slam: it hits for 70% of your shield''s armor, then stuns enemies in front and silences their spells for 2 seconds.$B$BBerserker Stance - a two-handed weapon (picked from your bags too). Your charge attack is Leaping Strike: your attack power, through all armor, on every enemy in front. Each one that lands gives Berserker''s Fury, up to 10 stacks of 10% more attack power and spell power, and each stack heals you for 1% of your maximum health on every critical strike you land.$B$BAll one-handed weapons swing every 2.70 seconds and all two-handers every 4.00, so pick by damage!','Warriors fight in three stances. Q and E switch between them.$B$BBattle Stance - any weapon. Your charge attack is the Spin Attack, which hits everyone around you. With two weapons it hits twice as many times.$B$BDefensive Stance - a one-handed weapon and a shield (taking the stance picks them from your bags). Your charge attack is Shield Slam: it hits for 70% of your shield''s armor, then stuns enemies in front and silences their spells for 2 seconds.$B$BBerserker Stance - a two-handed weapon (picked from your bags too). Your charge attack is Leaping Strike: your attack power, through all armor, on every enemy in front. Each one that lands gives Berserker''s Fury, up to 10 stacks of 10% more attack power and spell power, and each stack heals you for 1% of your maximum health on every critical strike you land.$B$BAll one-handed weapons swing every 2.70 seconds and all two-handers every 4.00, so pick by damage!',0,1,0,1),
(900624,'You grow stronger by gaining experience - the purple bar at the bottom.$B$BYou get experience from finishing quests and defeating enemies. Fill the bar and you reach the next level: more health, better stats, and a talent point from level 10.$B$BEnemies inside dungeons and raids give half the experience, but they drop much better treasure.$B$BEnemies far below your level give little or nothing, so keep moving to new places!$B$BWorthy foes sometimes drop a Piece of Heart. Bring me four and you''ll get a whole new heart. That means you get tougher!','You grow stronger by gaining experience - the purple bar at the bottom.$B$BYou get experience from finishing quests and defeating enemies. Fill the bar and you reach the next level: more health, better stats, and a talent point from level 10.$B$BEnemies inside dungeons and raids give half the experience, but they drop much better treasure.$B$BEnemies far below your level give little or nothing, so keep moving to new places!$B$BWorthy foes sometimes drop a Piece of Heart. Bring me four and you''ll get a whole new heart. That means you get tougher!',0,1,0,1),
(900625,'Your stats! Press 8 - the Combat Stats panel sits beside your character sheet.$B$BStrength - attack power: harder hits with every weapon and charge attack.$BAgility - more critical strikes, dodges and armor.$BStamina - more health.$BIntellect - here it gives spell power, so your healing and magic hit harder.$BSpirit - you recover health faster.$BArmor - less damage from physical blows.$B$BSpell power also makes the magic in your gear stronger: every spell an item casts, like a weapon''s chance on hit or a trinket''s use, gets 45% of it.$B$BCritical strikes hit for double. Your hit chance decides how often you miss.','Your stats! Press 8 - the Combat Stats panel sits beside your character sheet.$B$BStrength - attack power: harder hits with every weapon and charge attack.$BAgility - more critical strikes, dodges and armor.$BStamina - more health.$BIntellect - here it gives spell power, so your healing and magic hit harder.$BSpirit - you recover health faster.$BArmor - less damage from physical blows.$B$BSpell power also makes the magic in your gear stronger: every spell an item casts, like a weapon''s chance on hit or a trinket''s use, gets 45% of it.$B$BCritical strikes hit for double. Your hit chance decides how often you miss.',0,1,0,1),
(900626,'Talents make you special!$B$BFrom level 10 you get one talent point every level. Press 9 and turn to Talents to spend them.$B$BEach tree has rows. Put 5 points into a tree to open its next row. Read a talent''s tooltip to see what every point does.$B$BSome favorites: Toughness makes your shield stronger, and your Shield Slam with it. Bleeding Edge makes enemies bleed. Deep Wounds bleeds them when you crit. The weapon specializations give counterattacks, enrages and a Shield Cleave, depending on what you hold.$B$BChanged your mind? A class trainer can reset your talents for some gold.','Talents make you special!$B$BFrom level 10 you get one talent point every level. Press 9 and turn to Talents to spend them.$B$BEach tree has rows. Put 5 points into a tree to open its next row. Read a talent''s tooltip to see what every point does.$B$BSome favorites: Toughness makes your shield stronger, and your Shield Slam with it. Bleeding Edge makes enemies bleed. Deep Wounds bleeds them when you crit. The weapon specializations give counterattacks, enrages and a Shield Cleave, depending on what you hold.$B$BChanged your mind? A class trainer can reset your talents for some gold.',0,1,0,1),
(900627,'Press 8 to open your character and all your bags at once.$B$BTo put something on, right-click it in your bag, or drag it onto its slot on your character. Hover over an item in your bags to see what you''re wearing in that slot next to it.$B$BGrey junk and plain white gear are sold for you at vendors. Sold something by mistake? A pawnbroker buys it back until you log out.$B$BYou carry up to 10 of each potion, and potions have no cooldown. Mana potions turn into a shield that absorbs damage! Right-click one to put it on key 6.$B$BRight-click a mount to put it on key 7. Swinging your sword while riding gets you off.$B$BLoot is picked up for you automatically.','Press 8 to open your character and all your bags at once.$B$BTo put something on, right-click it in your bag, or drag it onto its slot on your character. Hover over an item in your bags to see what you''re wearing in that slot next to it.$B$BGrey junk and plain white gear are sold for you at vendors. Sold something by mistake? A pawnbroker buys it back until you log out.$B$BYou carry up to 10 of each potion, and potions have no cooldown. Mana potions turn into a shield that absorbs damage! Right-click one to put it on key 6.$B$BRight-click a mount to put it on key 7. Swinging your sword while riding gets you off.$B$BLoot is picked up for you automatically.',0,1,0,1),
(900628,'Items come in colors: grey is junk, white is common, green is uncommon, blue is rare, purple is epic, and orange is legendary!$B$BOne-handed weapons: swords, axes, maces, daggers and fist weapons. Two-handed weapons: swords, axes, maces, polearms and staves. Ranged weapons on key 2: bows, guns, crossbows and thrown weapons.$B$BYou can hold a one-hander with a shield, two one-handers at once, or one big two-hander. Each stance wants its own.$B$BWear several pieces of the same armor set to get set bonuses - the tooltip lists them.$B$BSome weapons have a ''Chance on hit'' or ''Use'' effect. Those grow with your spell power.$B$BClear a whole dungeon and you get its Crystal Shard. Collect them - someone might need them one day!','Items come in colors: grey is junk, white is common, green is uncommon, blue is rare, purple is epic, and orange is legendary!$B$BOne-handed weapons: swords, axes, maces, daggers and fist weapons. Two-handed weapons: swords, axes, maces, polearms and staves. Ranged weapons on key 2: bows, guns, crossbows and thrown weapons.$B$BYou can hold a one-hander with a shield, two one-handers at once, or one big two-hander. Each stance wants its own.$B$BWear several pieces of the same armor set to get set bonuses - the tooltip lists them.$B$BSome weapons have a ''Chance on hit'' or ''Use'' effect. Those grow with your spell power.$B$BClear a whole dungeon and you get its Crystal Shard. Collect them - someone might need them one day!',0,1,0,1),
(900629,'Dungeons are the best adventures!$B$BAsk any innkeeper for the dungeon list and they''ll send you to the dungeon''s meeting stone.$B$BInside, the bar under the minimap shows how many enemies you''ve defeated. Click it to find the ones still standing. Defeat all of them and you get the dungeon''s Crystal Shard!$B$BEnemies you defeat stay defeated, and the dungeon keeps waiting for you until you ask me to reset everything.$B$BIf you fall inside a dungeon, you come back at its entrance.$B$BPress M inside for the dungeon map. And watch for those Heavy Blows!','Dungeons are the best adventures!$B$BAsk any innkeeper for the dungeon list and they''ll send you to the dungeon''s meeting stone.$B$BInside, the bar under the minimap shows how many enemies you''ve defeated. Click it to find the ones still standing. Defeat all of them and you get the dungeon''s Crystal Shard!$B$BEnemies you defeat stay defeated, and the dungeon keeps waiting for you until you ask me to reset everything.$B$BIf you fall inside a dungeon, you come back at its entrance.$B$BPress M inside for the dungeon map. And watch for those Heavy Blows!',0,1,0,1),
(900630,'Getting around Azeroth!$B$BRun without stopping for 15 seconds and you start sprinting, twice as fast. You swim fast too, until you run out of breath.$B$BRide a mount (key 7) for long trips, or take a flight master''s gryphon or wind rider between towns.$B$BEvery town is friendly to you, Alliance and Horde alike, so you can go anywhere and talk to anyone.$B$BThe Kirin Tor mages in Stormwind''s Wizard''s Sanctum and outside Dalaran send you between the two.','Getting around Azeroth!$B$BRun without stopping for 15 seconds and you start sprinting, twice as fast. You swim fast too, until you run out of breath.$B$BRide a mount (key 7) for long trips, or take a flight master''s gryphon or wind rider between towns.$B$BEvery town is friendly to you, Alliance and Horde alike, so you can go anywhere and talk to anyone.$B$BThe Kirin Tor mages in Stormwind''s Wizard''s Sanctum and outside Dalaran send you between the two.',0,1,0,1),
(900631,'That''s me! Navi!$B$BOnce you wear my light, I follow you everywhere. While you fight, I heal a tenth of your health every 10 seconds.$B$BIf you fall, my light brings you back with some of your health and mana. After that I need 5 minutes to rest before I can do it again.$B$BI can also reset every dungeon and raid for you, so their enemies come back for another try.$B$BAnd I give you errands along the way. Hey! Listen! They''re important!','That''s me! Navi!$B$BOnce you wear my light, I follow you everywhere. While you fight, I heal a tenth of your health every 10 seconds.$B$BIf you fall, my light brings you back with some of your health and mana. After that I need 5 minutes to rest before I can do it again.$B$BI can also reset every dungeon and raid for you, so their enemies come back for another try.$B$BAnd I give you errands along the way. Hey! Listen! They''re important!',0,1,0,1),
(900640,'Professions let you gather and make your own things!$B$BYou can learn two main professions, plus all three secondary ones: Cooking, First Aid and Fishing. Trainers are in every big city - ask a guard where to find them.$B$BGathering goes well with crafting: Mining with Blacksmithing or Engineering, Herbalism with Alchemy, Skinning with Leatherworking. Tailoring and Enchanting both use cloth and the gear you find.$B$BHere, herbs, veins, skinned beasts, fish and disenchanted items all give you 5 times as much, and a herb or vein is gathered all in one go. A recipe only needs materials from its own profession - any others it would ask for are skipped!$B$BSkill goes up to 75, then 150, 225 and 300. Visit your trainer to learn the next rank: Journeyman from level 10, Expert from level 20, Artisan from level 35.','Professions let you gather and make your own things!$B$BYou can learn two main professions, plus all three secondary ones: Cooking, First Aid and Fishing. Trainers are in every big city - ask a guard where to find them.$B$BGathering goes well with crafting: Mining with Blacksmithing or Engineering, Herbalism with Alchemy, Skinning with Leatherworking. Tailoring and Enchanting both use cloth and the gear you find.$B$BHere, herbs, veins, skinned beasts, fish and disenchanted items all give you 5 times as much, and a herb or vein is gathered all in one go. A recipe only needs materials from its own profession - any others it would ask for are skipped!$B$BSkill goes up to 75, then 150, 225 and 300. Visit your trainer to learn the next rank: Journeyman from level 10, Expert from level 20, Artisan from level 35.',0,1,0,1),
(900641,'Alchemy turns herbs into potions and elixirs!$B$BYou make healing potions, mana potions, elixirs that raise your stats for a while, and later flasks and transmutes. Most recipes need herbs and an empty vial - vials are sold by trade supply vendors.$B$BHere, a mana potion becomes a shield that absorbs damage. You carry up to 10 of each potion, and potions have no cooldown, so drink as many as you need!$B$BLearn Herbalism too, and you''ll never run out of herbs.','Alchemy turns herbs into potions and elixirs!$B$BYou make healing potions, mana potions, elixirs that raise your stats for a while, and later flasks and transmutes. Most recipes need herbs and an empty vial - vials are sold by trade supply vendors.$B$BHere, a mana potion becomes a shield that absorbs damage. You carry up to 10 of each potion, and potions have no cooldown, so drink as many as you need!$B$BLearn Herbalism too, and you''ll never run out of herbs.',0,1,0,1),
(900642,'Blacksmithing hammers metal into weapons and armor!$B$BYou make swords, axes, maces, mail and plate armor, shield spikes, and sharpening stones and weightstones that make your weapon hit harder for a while.$B$BYou need a Blacksmith Hammer and an anvil, and metal bars. Miners smelt ore into bars at a forge, so Mining is the perfect partner.$B$BLater on, blacksmiths can choose to become armorsmiths or weaponsmiths and learn special recipes.','Blacksmithing hammers metal into weapons and armor!$B$BYou make swords, axes, maces, mail and plate armor, shield spikes, and sharpening stones and weightstones that make your weapon hit harder for a while.$B$BYou need a Blacksmith Hammer and an anvil, and metal bars. Miners smelt ore into bars at a forge, so Mining is the perfect partner.$B$BLater on, blacksmiths can choose to become armorsmiths or weaponsmiths and learn special recipes.',0,1,0,1),
(900643,'Enchanting puts magic on your gear!$B$BFirst you disenchant: break a green, blue or purple item you don''t need into dust, essences and shards. Then you use them to enchant your weapons and armor with more stats, damage or protection. Here you get 5 times the dust and essences!$B$BYou need an enchanting rod, which you make yourself from a copper rod and some materials.$B$BEnchanting needs no gathering profession - every unwanted green item is a gift!','Enchanting puts magic on your gear!$B$BFirst you disenchant: break a green, blue or purple item you don''t need into dust, essences and shards. Then you use them to enchant your weapons and armor with more stats, damage or protection. Here you get 5 times the dust and essences!$B$BYou need an enchanting rod, which you make yourself from a copper rod and some materials.$B$BEnchanting needs no gathering profession - every unwanted green item is a gift!',0,1,0,1),
(900644,'Engineering builds gadgets! Booms! Whirrs! Things that probably shouldn''t work!$B$BYou make bombs and dynamite, guns and scopes for your ranged weapon, goggles, mechanical pets, target dummies and all sorts of tools.$B$BYou need a Blacksmith Hammer and an Arclight Spanner, metal bars and stone, so take Mining with it.$B$BLater on, engineers choose to become Gnomish or Goblin engineers for even stranger inventions.','Engineering builds gadgets! Booms! Whirrs! Things that probably shouldn''t work!$B$BYou make bombs and dynamite, guns and scopes for your ranged weapon, goggles, mechanical pets, target dummies and all sorts of tools.$B$BYou need a Blacksmith Hammer and an Arclight Spanner, metal bars and stone, so take Mining with it.$B$BLater on, engineers choose to become Gnomish or Goblin engineers for even stranger inventions.',0,1,0,1),
(900645,'Herbalism lets you pick herbs!$B$BTurn on Find Herbs from your spellbook and herbs show up on your minimap as little yellow dots. Walk up and click one to gather it.$B$BHere, each herb gives you 5 times as much, all at once. Higher-level herbs need more skill, and you get skill by picking.$B$BAlchemists need herbs for everything, so Herbalism and Alchemy go together like hearts and fairies!','Herbalism lets you pick herbs!$B$BTurn on Find Herbs from your spellbook and herbs show up on your minimap as little yellow dots. Walk up and click one to gather it.$B$BHere, each herb gives you 5 times as much, all at once. Higher-level herbs need more skill, and you get skill by picking.$B$BAlchemists need herbs for everything, so Herbalism and Alchemy go together like hearts and fairies!',0,1,0,1),
(900646,'Leatherworking makes leather and mail armor!$B$BYou make armor, armor kits that add armor to your gear, cloaks, and quivers and ammo pouches for your arrows and bullets.$B$BYou need leather and hides, which come from Skinning. Some recipes also use salt, thread and dyes from trade supply vendors.$B$BLater on, leatherworkers can choose Elemental, Dragonscale or Tribal Leatherworking.','Leatherworking makes leather and mail armor!$B$BYou make armor, armor kits that add armor to your gear, cloaks, and quivers and ammo pouches for your arrows and bullets.$B$BYou need leather and hides, which come from Skinning. Some recipes also use salt, thread and dyes from trade supply vendors.$B$BLater on, leatherworkers can choose Elemental, Dragonscale or Tribal Leatherworking.',0,1,0,1),
(900647,'Mining lets you dig ore from veins in the ground!$B$BTurn on Find Minerals from your spellbook and veins show up on your minimap. You need a Mining Pick in your bags.$B$BHere, a vein gives you 5 times the ore and is mined all in one go.$B$BTake your ore to a forge to smelt it into bars. Blacksmiths and engineers need lots of bars, and you might find gems too!','Mining lets you dig ore from veins in the ground!$B$BTurn on Find Minerals from your spellbook and veins show up on your minimap. You need a Mining Pick in your bags.$B$BHere, a vein gives you 5 times the ore and is mined all in one go.$B$BTake your ore to a forge to smelt it into bars. Blacksmiths and engineers need lots of bars, and you might find gems too!',0,1,0,1),
(900648,'Skinning takes leather and hides from beasts!$B$BAfter you defeat and loot a beast, click its body to skin it. You need a Skinning Knife in your bags.$B$BBigger, higher-level beasts need more skill. You get 5 times the leather here.$B$BLeatherworkers turn your leather into armor, so Skinning and Leatherworking are best friends!','Skinning takes leather and hides from beasts!$B$BAfter you defeat and loot a beast, click its body to skin it. You need a Skinning Knife in your bags.$B$BBigger, higher-level beasts need more skill. You get 5 times the leather here.$B$BLeatherworkers turn your leather into armor, so Skinning and Leatherworking are best friends!',0,1,0,1),
(900649,'Tailoring sews cloth into armor and bags!$B$BYou make cloth armor, shirts, and best of all, bags - more room for treasure!$B$BYou need cloth, which humanoid enemies drop: linen, then wool, silk, mageweave and runecloth. First turn the cloth into bolts, then sew. Thread and dyes come from trade supply vendors.$B$BTailoring needs no gathering profession. Every bandit you defeat is a supplier!','Tailoring sews cloth into armor and bags!$B$BYou make cloth armor, shirts, and best of all, bags - more room for treasure!$B$BYou need cloth, which humanoid enemies drop: linen, then wool, silk, mageweave and runecloth. First turn the cloth into bolts, then sew. Thread and dyes come from trade supply vendors.$B$BTailoring needs no gathering profession. Every bandit you defeat is a supplier!',0,1,0,1),
(900650,'Cooking turns meat and fish into food!$B$BEating good food restores your health while you sit, and many dishes give you a Well Fed bonus that raises your stats for a while.$B$BYou need ingredients from beasts and fish, and a fire - your Basic Campfire, a cooking fire in town, or any campfire you find.$B$BCooking is a secondary profession, so you can learn it along with your two main ones.','Cooking turns meat and fish into food!$B$BEating good food restores your health while you sit, and many dishes give you a Well Fed bonus that raises your stats for a while.$B$BYou need ingredients from beasts and fish, and a fire - your Basic Campfire, a cooking fire in town, or any campfire you find.$B$BCooking is a secondary profession, so you can learn it along with your two main ones.',0,1,0,1),
(900651,'First Aid makes bandages!$B$BYou make bandages from cloth - linen, wool, silk, mageweave, runecloth. A bandage heals you over a few seconds, as long as you aren''t hit.$B$BHere, you can use one bandage right after another!$B$BFirst Aid is a secondary profession. Trainers teach the first ranks, Expert comes from a book sold by some vendors, and Artisan from a field medic''s quest.','First Aid makes bandages!$B$BYou make bandages from cloth - linen, wool, silk, mageweave, runecloth. A bandage heals you over a few seconds, as long as you aren''t hit.$B$BHere, you can use one bandage right after another!$B$BFirst Aid is a secondary profession. Trainers teach the first ranks, Expert comes from a book sold by some vendors, and Artisan from a field medic''s quest.',0,1,0,1),
(900652,'Fishing! The best way to spend a quiet afternoon.$B$BYou need a fishing pole. Equip it, use Fishing near water, and wait until the bobber splashes - then click it, quick!$B$BHere, every catch gives you 5 times the fish and raises your Fishing skill by 10, so you get better really fast.$B$BLures make you catch things more easily. You can cook your fish, and sometimes you find treasure too!','Fishing! The best way to spend a quiet afternoon.$B$BYou need a fishing pole. Equip it, use Fishing near water, and wait until the bobber splashes - then click it, quick!$B$BHere, every catch gives you 5 times the fish and raises your Fishing skill by 10, so you get better really fast.$B$BLures make you catch things more easily. You can cook your fish, and sometimes you find treasure too!',0,1,0,1);
